// ============================================================
// Rule: EPM_Endpoint Added to Monitored Group
// Vendor: BeyondTrust
// Objective:
// Detect activity associated with EPM_Endpoint Added to Monitored Group.
// Severity: SEV_030_MEDIUM
// Category: PRIVILEGE_ESCALATION
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0004 - Privilege Escalation

// Configuração inicial: define o dataset de origem dos logs do BeyondTrust EPM  
// O dataset 'beyondtrust_epm_raw' contém eventos gerados pela solução BeyondTrust Endpoint Privilege Management (EPM)  
// Esses eventos incluem ações administrativas, adição de usuários a grupos e alterações de políticas de privilégio  
dataset = beyondtrust_epm_raw  

// Criação (ou renomeação) de campos para facilitar a leitura e análise  
// O operador '->' acessa atributos dentro da estrutura JSON do campo 'event'  
| alter 
    action = event -> action,   // Ação registrada no evento (ex: inclusão de usuário em grupo)  
    reason = event -> reason    // Motivo associado à ação (ex: justificativa ou descrição do evento)  

// Filtro para retornar apenas eventos cujo motivo indique adição de novo computador  
// ao grupo "SI" — grupo classificado como sensível devido a privilégios elevados  
| filter reason = "New computer to group SI "

// Seleção dos campos relevantes para exibição e correlação  
// Esses campos são úteis para auditoria e investigação de movimentações privilegiadas  
| fields 
    action,    // Ação executada (ex: Add to Group)  
    user,      // Usuário associado à ação  
    reason     // Motivo ou descrição da inclusão
